#!/usr/bin/env python3
"""Read ids.txt and print the next order id.

Ids have the form ORD- followed by four base-36 characters (0-9, A-Z).
The file lists one id per line, most recent last.
"""

import sys

BASE36 = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def to_int(suffix: str) -> int:
    """Convert a 4-character base-36 suffix to an integer."""
    val = 0
    for ch in suffix:
        val = val * 36 + BASE36.index(ch)
    return val


def to_base36(val: int, width: int = 4) -> str:
    """Format an integer as a zero-padded base-36 string of the given width."""
    digits = []
    for _ in range(width):
        digits.append(BASE36[val % 36])
        val //= 36
    if val != 0:
        print("Overflow: no more ids available", file=sys.stderr)
        sys.exit(1)
    return "".join(reversed(digits))


def main() -> None:
    try:
        with open("ids.txt") as f:
            lines = [line.strip() for line in f if line.strip()]
    except FileNotFoundError:
        lines = []

    if not lines:
        print("ORD-0000")
        return

    current = lines[-1]
    suffix = current.split("-", 1)[1]
    next_val = to_int(suffix) + 1
    print(f"ORD-{to_base36(next_val)}")


if __name__ == "__main__":
    main()

