#!/usr/bin/env python3
"""Read events.jsonl, remove duplicate events sharing an event_id (keep last),
and write the remaining events to deduped.jsonl."""

import json

INPUT = "events.jsonl"
OUTPUT = "deduped.jsonl"

def main():
    seen = {}
    with open(INPUT) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            event = json.loads(line)
            seen[event["event_id"]] = line  # overwrite -> keep last occurrence

    with open(OUTPUT, "w") as f:
        for line in seen.values():
            f.write(line + "\n")

    print(f"Wrote {len(seen)} unique events to {OUTPUT}")

if __name__ == "__main__":
    main()

