"""Read events.jsonl, deduplicate by event_id, write deduped.jsonl."""

import json

seen: dict[str, dict] = {}

with open("events.jsonl") as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        event = json.loads(line)
        seen[event["event_id"]] = event  # last occurrence wins

with open("deduped.jsonl", "w") as f:
    for event in seen.values():
        f.write(json.dumps(event, separators=(",", ":")) + "\n")

