#!/usr/bin/env python3
import os
import re

REPORTS_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "reports")


def report_order(name: str) -> tuple:
    """Sort key: extract numeric suffix after 'report-' for natural ordering."""
    m = re.search(r"report-(\d+)", name)
    return (int(m.group(1)),) if m else (float("inf"), name)


def main() -> None:
    try:
        files = sorted(os.listdir(REPORTS_DIR), key=report_order)
    except FileNotFoundError:
        return

    for f in files:
        print(f)


if __name__ == "__main__":
    main()

