#!/usr/bin/env python3
"""Print report file names under reports/ in report order."""

import os
import re

REPORTS_DIR = "reports"


def report_key(name: str) -> int:
    """Extract the numeric suffix from a report filename for sorting."""
    m = re.search(r"report-(\d+)\.txt$", name)
    if m is None:
        return -1
    return int(m.group(1))


def main() -> None:
    try:
        names = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        return

    reports = sorted(
        (n for n in names if re.match(r"report-\d+\.txt$", n)),
        key=report_key,
    )
    for r in reports:
        print(r)


if __name__ == "__main__":
    main()

