from datetime import datetime, timezone, timedelta


def parse_timestamp(line: str) -> datetime | None:
    """Parse 'YYYY-MM-DD HH:MM:SS' prefix from a log line."""
    if len(line) < 19:
        return None
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S").replace(
            tzinfo=timezone.utc
        )
    except ValueError:
        return None


def main() -> None:
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp.", file=sys.stderr)
        sys.exit(1)

    as_of_dt = datetime.fromtimestamp(as_of, tz=timezone.utc)
    cutoff = as_of_dt - timedelta(days=7)

    with open("app.log") as f:
        lines = f.readlines()

    fresh: list[str] = []
    stale: list[str] = []

    for line in lines:
        ts = parse_timestamp(line)
        if ts is not None and ts < cutoff:
            stale.append(line)
        else:
            fresh.append(line)

    with open("app.log", "w") as f:
        f.writelines(fresh)

    with open("archive.log", "a") as f:
        f.writelines(stale)


if __name__ == "__main__":
    main()

import sys
from datetime import datetime


def parse_timestamp(line: str):
    """Parse the YYYY-MM-DD HH:MM:SS prefix from a log line."""
    try:
        return datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S")
    except (ValueError, IndexError):
        return None


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff_ts = as_of - 7 * 86400  # 7 days in seconds

    with open("app.log", "r") as f:
        lines = f.readlines()

    keep = []
    archive = []

    for line in lines:
        stripped = line.rstrip("\n")
        if not stripped:
            # Preserve blank lines in app.log
            keep.append(stripped)
            continue
        dt = parse_timestamp(stripped)
        if dt is not None and dt.timestamp() < cutoff_ts:
            archive.append(stripped)
        else:
            keep.append(stripped)

    # Append to archive.log
    if archive:
        with open("archive.log", "a") as f:
            for line in archive:
                f.write(line + "\n")

    # Rewrite app.log with remaining entries
    with open("app.log", "w") as f:
        for line in keep:
            f.write(line + "\n")


if __name__ == "__main__":
    main()

